      {/* Results panels (shown after workflow completes) */}
      {isComplete && (
        <>
          {/* Projects panel */}
          {projects && (
            <div className="rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft">
              <h2 className="mb-3 font-serif text-base font-semibold text-plum">
