import { useState, useRef, useEffect, useCallback } from 'react'
import { ChevronDown, GitBranch, Check, Bell, User, Settings, LogOut, Loader2, CheckCheck } from 'lucide-react'
import { getProfile, updateProfile } from '../services/api/profile'
import { getNotifications, getNotificationSummary, markNotificationRead, markAllNotificationsRead } from '../services/api/notifications'

// ── helpers ────────────────────────────────────────────────────────────────────

/** Derive two-character initials from a name string. */
function initials(name) {
  if (!name) return '?'
  const parts = name.trim().split(/\s+/)
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
}

/** Friendly relative timestamp. */
function timeAgo(isoString) {
  if (!isoString) return ''
  const diff = Date.now() - new Date(isoString).getTime()
  const mins  = Math.floor(diff / 60_000)
  const hours = Math.floor(diff / 3_600_000)
  const days  = Math.floor(diff / 86_400_000)
  if (mins  < 1)  return 'just now'
  if (mins  < 60) return `${mins}m ago`
  if (hours < 24) return `${hours}h ago`
  return `${days}d ago`
}

const EVENT_LABELS = {
  REVIEW_COMPLETED: 'Review completed',
  NEW_FINDINGS:     'New findings',
  TESTS_GENERATED:  'Tests generated',
  GENERAL:          'Notice',
}

// ── Component ──────────────────────────────────────────────────────────────────

export default function Topbar({ projects = [], activeProject, setActiveProject }) {
  const [activeMenu, setActiveMenu] = useState(null)

  // Profile state
  const [profile,      setProfile]      = useState(null)
  const [editingName,  setEditingName]  = useState(false)
  const [nameInput,    setNameInput]    = useState('')
  const [savingName,   setSavingName]   = useState(false)
  const [profileError, setProfileError] = useState('')

  // Notification state
  const [notifications,  setNotifications]  = useState([])
  const [unreadCount,    setUnreadCount]    = useState(0)
  const [notifLoading,   setNotifLoading]   = useState(false)

  const projectRef      = useRef(null)
  const notificationsRef = useRef(null)
  const profileRef      = useRef(null)

  // ── load profile once ──────────────────────────────────────────────────────
  useEffect(() => {
    getProfile()
      .then(p => { setProfile(p); setNameInput(p.name) })
      .catch(() => {}) // profile missing — show fallback, don't crash
  }, [])

  // ── load / refresh notifications whenever the panel opens ─────────────────
  const loadNotifications = useCallback(async () => {
    setNotifLoading(true)
    try {
      const [list, summary] = await Promise.all([
        getNotifications(),
        getNotificationSummary(),
      ])
      setNotifications(list || [])
      setUnreadCount(summary?.unread ?? 0)
    } catch {
      // silently skip — don't block the UI
    } finally {
      setNotifLoading(false)
    }
  }, [])

  useEffect(() => {
    if (activeMenu === 'notifications') loadNotifications()
  }, [activeMenu, loadNotifications])

  // Poll unread count every 30 s even when the panel is closed
  useEffect(() => {
    const tick = () =>
      getNotificationSummary()
        .then(s => setUnreadCount(s?.unread ?? 0))
        .catch(() => {})
    tick()
    const id = setInterval(tick, 30_000)
    return () => clearInterval(id)
  }, [])

  // ── click-outside / Escape to close ───────────────────────────────────────
  useEffect(() => {
    const onDown = (e) => {
      const inside = [projectRef, notificationsRef, profileRef]
        .some(r => r.current?.contains(e.target))
      if (!inside) setActiveMenu(null)
    }
    const onKey = (e) => { if (e.key === 'Escape') setActiveMenu(null) }
    document.addEventListener('mousedown', onDown)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onDown)
      document.removeEventListener('keydown', onKey)
    }
  }, [])

  // ── profile name editing ───────────────────────────────────────────────────
  const handleSaveName = async () => {
    if (!nameInput.trim()) return
    setSavingName(true)
    setProfileError('')
    try {
      const updated = await updateProfile({ name: nameInput.trim() })
      setProfile(updated)
      setEditingName(false)
    } catch (e) {
      setProfileError(e?.message || 'Failed to save name')
    } finally {
      setSavingName(false)
    }
  }

  // ── mark a single notification read ───────────────────────────────────────
  const handleMarkRead = async (id) => {
