import { useState, useEffect } from "react"
import { apiRequest } from "../services/api/client"
import { useAuth } from "../hooks/useAuth"

function Toggle({ checked, onChange, disabled }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      onClick={() => onChange(!checked)}
