package com.thirdeye.backend.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Single-row user profile table.
 *
 * There is no authentication in this application: one profile row is
 * created on first access (id = 1) and can be updated via PATCH /api/profile.
 * The name and email are editable; they are persisted in H2.
 */
@Entity
@Table(name = "user_profile")
public class UserProfile {

    @Id
    private Long id = 1L;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String email;

    private LocalDateTime updatedAt = LocalDateTime.now();

    public UserProfile() {}

    public UserProfile(String name, String email) {
        this.name  = name;
        this.email = email;
    }

    @PreUpdate
    public void touch() { this.updatedAt = LocalDateTime.now(); }

    // ── accessors ────────────────────────────────────────────────────────────

    public Long getId()                    { return id; }
    public String getName()               { return name; }
    public void   setName(String name)    { this.name = name; }
    public String getEmail()              { return email; }
    public void   setEmail(String email)  { this.email = email; }
    public LocalDateTime getUpdatedAt()   { return updatedAt; }
