                          onChange={e => setNameInput(e.target.value)}
                          onKeyDown={e => { if (e.key === 'Enter') handleSaveName(); if (e.key === 'Escape') setEditingName(false) }}
                          className="w-full rounded-md border border-plum/30 bg-sand/40 px-2 py-1 text-sm text-plum outline-none focus:border-plum"
                        />
                        <button onClick={handleSaveName} disabled={savingName}
                          className="shrink-0 rounded-md bg-plum px-2 py-1 text-[11px] font-medium text-white disabled:opacity-50">
                          {savingName ? '�?�' : 'Save'}
                        </button>
                      </div>
                    ) : (
                      <p className="truncate text-sm font-semibold text-plum">{displayName}</p>
                    )}
                    {displayEmail && (
                      <p className="truncate text-xs text-plum/50">{displayEmail}</p>
                    )}
                    {profileError && (
                      <p className="mt-1 text-[11px] text-coral">{profileError}</p>
                    )}
                  </div>
                </div>
              </div>

              {/* Actions */}
              <div className="py-1.5">
                <button
                  onClick={() => { setEditingName(true); setProfileError('') }}
                  className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-plum/70 hover:bg-sand/50 hover:text-plum transition-colors"
                >
                  <User size={15} /> Edit name
                </button>
                <button
                  className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-plum/70 hover:bg-sand/50 hover:text-plum transition-colors"
                  onClick={() => setActiveMenu(null)}
                >
                  <Settings size={15} /> Settings
                </button>
                <button
                  className="flex w-full items-center gap-3 px-4 py-2.5 text-sm text-plum/70 hover:bg-sand/50 hover:text-plum transition-colors"
                  onClick={() => setActiveMenu(null)}
                >
                  <LogOut size={15} /> Log out
                </button>
              </div>
            </div>
          )}
        </div>

      </div>
    </header>
  )
}

import { NavLink } from 'react-router-dom'
import {
  Eye,
  LayoutGrid,
  GitCompare,
  ShieldAlert,
  FlaskConical,
  FileText,
  Bot,
  ChevronsLeft,
  ChevronsRight,
} from 'lucide-react'

const navItems = [
  { to: '/dashboard/overview', label: 'Overview', icon: LayoutGrid },
  { to: '/dashboard/diff', label: 'Code diff', icon: GitCompare },
  { to: '/dashboard/findings', label: 'Findings', icon: ShieldAlert },
  { to: '/dashboard/tests', label: 'Generated tests', icon: FlaskConical },
  { to: '/dashboard/report', label: 'Final report', icon: FileText },
  { to: '/dashboard/bob', label: 'IBM Bob', icon: Bot },
]

export default function Sidebar({ collapsed, onToggle }) {
  return (
    <aside
      className={`relative flex flex-col bg-plum text-ivory-100 transition-all duration-300 ease-out ${
        collapsed ? 'w-[76px]' : 'w-64'
      }`}
    >
      <div className="flex items-center gap-2.5 px-5 py-6">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-coral/90">
          <Eye size={18} strokeWidth={2.25} className="text-white" />
        </div>
        {!collapsed && (
          <span className="font-serif text-lg font-semibold tracking-tight whitespace-nowrap">
            ThirdEye AI
          </span>
        )}
      </div>

      <nav className="flex flex-1 flex-col gap-1 px-3">
        {navItems.map(({ to, label, icon: Icon }) => (
          <NavLink
            key={to}
            to={to}
            className={({ isActive }) =>
              `group flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors ${
                isActive
                  ? 'bg-white/10 text-white font-medium'
                  : 'text-ivory-100/65 hover:bg-white/5 hover:text-ivory-100'
              }`
            }
            title={collapsed ? label : undefined}
          >
            <Icon size={18} strokeWidth={2} className="shrink-0" />
            {!collapsed && <span className="whitespace-nowrap">{label}</span>}
          </NavLink>
        ))}
      </nav>

      <div className="border-t border-white/10 px-3 py-4">
        <button
          onClick={onToggle}
          className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-ivory-100/60 hover:bg-white/5 hover:text-ivory-100 transition-colors"
        >
          {collapsed ? <ChevronsRight size={18} /> : <ChevronsLeft size={18} />}
          {!collapsed && <span>Collapse</span>}
        </button>
      </div>
    </aside>
  )
}

