                  <span className="text-xs text-plum/55">{p.repositoryUrl || 'Repository not configured'}</span>
                </div>
                {p.id === activeProject.id && <Check size={16} className="text-coral" />}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Right-side controls */}
      <div className="flex items-center gap-3">

        {/* ── Notifications bell ── */}
