1 | #!/usr/bin/env node
2 | /**
3 |  * ThirdEye AI — IBM Bob MCP Server
4 |  *
5 |  * Exposes the ThirdEye Spring Boot API as tools so that IBM Bob can:
6 |  *   • list projects and their reviews
7 |  *   • create new code reviews
8 |  *   • read findings (with severity filtering)
9 |  *   • get a severity summary
10 |  *   • trigger or re-run analysis
11 |  *   • generate test stubs from findings
12 |  *
13 |  * This is the genuine IBM Bob integration for ThirdEye AI.
14 |  * Bob can invoke these tools from its chat panel to drive the full
15 |  * code-review workflow without leaving the IDE.
16 |  *
17 |  * Configuration (environment variables):
18 |  *   THIRDEYE_API_BASE_URL   URL of the running Spring Boot backend
19 |  *                           (default: http://localhost:8080)
20 |  *
21 |  * Register in Bob's mcp.json:
22 |  * {
23 |  *   "mcpServers": {
24 |  *     "thirdeye": {
25 |  *       "command": "node",
26 |  *       "args": ["/absolute/path/to/thirdeye-mcp/build/index.js"],
27 |  *       "env": {
28 |  *         "THIRDEYE_API_BASE_URL": "http://localhost:8080"
29 |  *       }
30 |  *     }
31 |  *   }
32 |  * }
33 |  */
34 | 
35 | import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
36 | import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
37 | import { z } from "zod";
38 | 
39 | // ── Configuration ──────────────────────────────────────────────────────────────
40 | 
41 | const BASE_URL = (process.env.THIRDEYE_API_BASE_URL ?? "http://localhost:8080").replace(/\/+$/, "");
42 | 
43 | // ── HTTP helper ────────────────────────────────────────────────────────────────
44 | 
45 | async function api(method: string, path: string, body?: unknown): Promise<unknown> {
46 |   const url = `${BASE_URL}${path}`;
47 |   const opts: RequestInit = {
48 |     method,
49 |     headers: { "Content-Type": "application/json", Accept: "application/json" },
50 |   };
51 |   if (body !== undefined) opts.body = JSON.stringify(body);
52 | 
53 |   const res = await fetch(url, opts);
54 |   const text = await res.text();
55 | 
56 |   let data: unknown;
57 |   try { data = JSON.parse(text); } catch { data = text; }
58 | 
59 |   if (!res.ok) {
60 |     const msg = (data && typeof data === "object" && data !== null && "message" in data)
61 |       ? (data as Record<string, unknown>).message
62 |       : text;
63 |     throw new Error(`ThirdEye API ${method} ${path} → ${res.status}: ${msg}`);
64 |   }
65 |   return data;
66 | }
67 | 
68 | function ok(text: string) {
69 |   return { content: [{ type: "text" as const, text }] };
70 | }
71 | function err(e: unknown) {
72 |   return { content: [{ type: "text" as const, text: String(e) }], isError: true as const };
73 | }
74 | 
75 | // ── MCP Server ─────────────────────────────────────────────────────────────────
76 | 
77 | const server = new McpServer({ name: "thirdeye", version: "0.1.0" });
78 | 
79 | // ── Tool: list_projects ────────────────────────────────────────────────────────
80 | server.registerTool(
81 |   "list_projects",
82 |   {
83 |     description:
84 |       "List all ThirdEye AI projects. Returns id, name, description, repositoryUrl, and status for each project.",
85 |     inputSchema: z.object({}),
86 |   },
87 |   async () => {
88 |     try {
89 |       return ok(JSON.stringify(await api("GET", "/api/projects"), null, 2));
90 |     } catch (e) { return err(e); }
91 |   }
92 | );
93 | 
94 | // ── Tool: list_reviews ─────────────────────────────────────────────────────────
95 | server.registerTool(
96 |   "list_reviews",
97 |   {
98 |     description:
99 |       "List all reviews for a ThirdEye project. Returns id, title, status (PENDING/ANALYZING/COMPLETED/FAILED), progress (0-100), and change stats.",
100 |     inputSchema: z.object({
101 |       projectId: z.number().int().positive().describe("Numeric project ID"),
102 |     }),
103 |   },
104 |   async ({ projectId }) => {
105 |     try {
106 |       return ok(JSON.stringify(await api("GET", `/api/projects/${projectId}/reviews`), null, 2));
107 |     } catch (e) { return err(e); }
108 |   }
109 | );
110 | 
111 | // ── Tool: get_review ───────────────────────────────────────────────────────────
112 | server.registerTool(
113 |   "get_review",
114 |   {
115 |     description:
116 |       "Get a single ThirdEye review by ID. Includes status, progress, and change statistics. Poll this tool to watch analysis progress.",
117 |     inputSchema: z.object({
118 |       reviewId: z.number().int().positive().describe("Numeric review ID"),
119 |     }),
120 |   },
121 |   async ({ reviewId }) => {
122 |     try {
123 |       return ok(JSON.stringify(await api("GET", `/api/reviews/${reviewId}`), null, 2));
124 |     } catch (e) { return err(e); }
125 |   }
126 | );
127 | 
128 | // ── Tool: create_review ────────────────────────────────────────────────────────
129 | server.registerTool(
130 |   "create_review",
131 |   {
132 |     description:
133 |       "Submit a code diff to ThirdEye AI for review. The review is persisted immediately and asynchronous mock analysis starts automatically. Returns the created review with status PENDING.",
134 |     inputSchema: z.object({
135 |       projectId:    z.number().int().positive().describe("Project to attach the review to"),
136 |       title:        z.string().min(1).describe("Short descriptive title, e.g. 'fix: remove hardcoded token'"),
137 |       codeDiff:     z.string().describe("Unified diff string (output of git diff)"),
138 |       filesChanged: z.number().int().min(0).optional().default(1),
139 |       linesAdded:   z.number().int().min(0).optional().default(0),
140 |       linesRemoved: z.number().int().min(0).optional().default(0),
141 |       commits:      z.number().int().min(0).optional().default(1),
142 |     }),
143 |   },
144 |   async ({ projectId, title, codeDiff, filesChanged, linesAdded, linesRemoved, commits }) => {
145 |     try {
146 |       return ok(JSON.stringify(
147 |         await api("POST", `/api/projects/${projectId}/reviews`, {
148 |           title, codeDiff, filesChanged, linesAdded, linesRemoved, commits,
149 |         }),
150 |         null, 2
151 |       ));
152 |     } catch (e) { return err(e); }
153 |   }
154 | );
155 | 
156 | // ── Tool: trigger_analysis ─────────────────────────────────────────────────────
157 | server.registerTool(
158 |   "trigger_analysis",
159 |   {
160 |     description:
161 |       "Re-run (or trigger) analysis for an existing ThirdEye review. Idempotent — existing findings are deleted before re-analysis. Returns the review with status reset to PENDING.",
162 |     inputSchema: z.object({
