58 |     @Transactional
59 |     public List<GeneratedTest> generateTests(Long reviewId) {
60 |         Review review = getReviewOrThrow(reviewId);
61 | 
62 |         if (!"COMPLETED".equals(review.getStatus())) {
63 |             throw new IllegalArgumentException(
64 |                 "Tests can only be generated for COMPLETED reviews. Current status: " + review.getStatus());
65 |         }
66 | 
67 |         // Clear previous generated tests (idempotent)
68 |         testRepository.deleteByReview_Id(reviewId);
69 | 
70 |         List<Finding> findings = findingRepository.findByReview_Id(reviewId);
71 |         List<GeneratedTest> tests = new ArrayList<>();
72 | 
73 |         for (Finding f : findings) {
74 |             String testName = buildTestName(f);
75 |             String testCode = buildTestCode(f);
76 |             String filename = buildFilename(f);
77 | 
78 |             tests.add(new GeneratedTest(
79 |                 review,
80 |                 testName,
81 |                 filename,
82 |                 "PENDING",   // [MOCK] Tests are never actually executed
83 |                 null,
84 |                 String.valueOf(f.getId()),
85 |                 testCode
86 |             ));
87 |         }
88 | 
89 |         // Add one general review-level test
90 |         tests.add(new GeneratedTest(
91 |             review,
92 |             "diff does not introduce new critical security findings",
93 |             "tests/security/review_" + reviewId + "_security.test.js",
94 |             "PENDING",
95 |             null,
96 |             null,
97 |             buildSecuritySmokeTest(review)
98 |         ));
99 | 
