107 |     private String buildTestName(Finding f) {
108 |         switch (f.getSeverity() == null ? "" : f.getSeverity().toLowerCase()) {
109 |             case "critical": return "should fail securely when: " + lowerFirst(f.getTitle());
110 |             case "high":     return "should reject unsafe input: " + lowerFirst(f.getTitle());
111 |             case "medium":   return "should handle edge case: " + lowerFirst(f.getTitle());
112 |             default:         return "should satisfy: " + lowerFirst(f.getTitle());
113 |         }
114 |     }
