  useEffect(() => {
    setLoading(true); setError(''); setReview(null); setFindings([])
    loadData()
  }, [loadData])

  useEffect(() => {
    if (!review) return
    if (review.status === 'COMPLETED' || review.status === 'FAILED') return
    const id = setInterval(loadData, 3000)
    return () => clearInterval(id)
  }, [review, loadData])

  if (loading) return (
    <div className="mx-auto flex max-w-5xl items-center justify-center py-20">
      <Loader2 size={24} className="animate-spin text-plum/40" />
    </div>
  )

  if (error) return (
    <div className="mx-auto max-w-5xl rounded-lg bg-coral/10 p-4 text-sm text-coral">{error}</div>
  )

  if (!review) return (
    <div className="mx-auto max-w-5xl rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-14 text-center text-sm text-plum/50">
      No reviews found for <strong>{activeProject.name}</strong>.{' '}
      <button onClick={() => navigate('/dashboard/diff')}
        className="font-medium text-terracotta-deep underline underline-offset-2">
        Submit a code diff
      </button>{' '}to get started.
    </div>
  )

  const stages        = buildStages(review.status, review.progress)
  const isRunning     = review.status === 'PENDING' || review.status === 'ANALYZING'
  const criticalCount = findings.filter(f => f.severity === 'critical').length
  const topFindings   = findings.filter(f => f.severity === 'critical' || f.severity === 'high')
  const statusLabel   = { PENDING: 'Queued', ANALYZING: 'In review', COMPLETED: 'Completed', FAILED: 'Failed' }[review.status] ?? review.status
  const statusBg      = { PENDING: 'bg-sand text-plum/70', ANALYZING: 'bg-coral-soft text-coral-deep', COMPLETED: 'bg-plum-50 text-plum', FAILED: 'bg-coral/10 text-coral-deep' }[review.status] ?? 'bg-sand text-plum/70'

  return (
    <div className="mx-auto flex max-w-5xl flex-col gap-7">

      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="font-serif text-2xl font-semibold text-plum">Review overview</h1>
          <p className="mt-1 text-sm text-plum/60">
            {activeProject.name} A� {review.commits} commit{review.commits !== 1 ? 's' : ''} A� #{review.id}: {review.title}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {isRunning && (
            <button onClick={loadData}
              className="flex items-center gap-1.5 rounded-full border border-sand-line bg-ivory-card px-3 py-1.5 text-xs text-plum/60 hover:text-plum transition-colors">
              <RefreshCw size={12} /> Refresh
            </button>
          )}
          <span className={`rounded-full px-3.5 py-1.5 text-sm font-medium ${statusBg}`}>{statusLabel}</span>
        </div>
      </div>

      {/* Progress + stats */}
      <div className="grid grid-cols-1 gap-5 md:grid-cols-[auto_1fr]">
        <div className="flex items-center gap-5 rounded-xl2 border border-sand-line bg-ivory-card p-6 shadow-soft">
          <ProgressRing
            progress={review.progress}
            sub={isRunning ? 'analysing�?�' : review.status === 'COMPLETED' ? 'complete' : review.status.toLowerCase()}
          />
          <div className="flex flex-col gap-2.5">
            {stages.map(s => (
              <div key={s.id} className="flex items-center gap-2.5">
                <span className={`flex h-5 w-5 items-center justify-center rounded-full ${stageStyle[s.state]}`}>
                  {stageIcon[s.state]}
                </span>
                <span className={`text-sm ${s.state === 'pending' ? 'text-plum/40' : 'text-plum font-medium'}`}>{s.label}</span>
              </div>
            ))}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
          <StatCard label="Files changed"  value={review.filesChanged} />
          <StatCard label="Lines added"    value={`+${review.linesAdded}`}   accent="terracotta" />
          <StatCard label="Lines removed"  value={`�^'${review.linesRemoved}`} />
          <StatCard label="Open findings"  value={findings.length} sub={`${criticalCount} critical`} accent="coral" />
        </div>
      </div>

      {/* Top findings (COMPLETED only) */}
      {review.status === 'COMPLETED' && (
        <div className="rounded-xl2 border border-sand-line bg-ivory-card p-6 shadow-soft">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="font-serif text-lg font-semibold text-plum">Needs your attention</h2>
            <button onClick={() => navigate('/dashboard/findings')}
              className="flex items-center gap-1 text-sm font-medium text-terracotta-deep hover:text-terracotta">
              See all findings <ArrowRight size={14} />
            </button>
          </div>
          {topFindings.length === 0
            ? <p className="text-sm text-plum/50">No critical or high findings �?" looking good!</p>
            : <div className="flex flex-col divide-y divide-sand-line">
                {topFindings.slice(0, 5).map(f => (
                  <div key={f.id} className="flex items-center justify-between gap-4 py-3.5 first:pt-0 last:pb-0">
                    <div className="flex items-center gap-3.5 min-w-0">
                      <SeverityBadge severity={f.severity} />
                      <div className="min-w-0">
                        <p className="truncate text-sm font-medium text-plum">{f.title}</p>
                        <p className="truncate text-xs text-plum/50 font-mono">{f.file}:{f.line}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
          }
        </div>
      )}

      {/* Running banner */}
      {isRunning && (
        <div className="flex items-center gap-3 rounded-xl2 border border-sand-line bg-ivory-card px-6 py-4 shadow-soft">
          <Loader2 size={16} className="animate-spin shrink-0 text-coral" />
          <p className="text-sm text-plum/70">Analysis is running in the background �?" this page refreshes automatically every 3 seconds.</p>
        </div>
      )}

      {/* FAILED banner */}
      {review.status === 'FAILED' && (
        <div className="rounded-xl2 border border-coral/25 bg-coral-soft/30 p-4 text-sm text-coral-deep">
          Analysis failed. You can re-trigger it from the{' '}
          <button onClick={() => navigate('/dashboard/diff')} className="font-medium underline underline-offset-2">Code diff</button> page.
        </div>
      )}

      {/* Human approval (COMPLETED only) */}
      {review.status === 'COMPLETED' && (
        <div className="rounded-xl2 border border-sand-line bg-ivory-card p-6 shadow-soft">
          <h2 className="font-serif text-lg font-semibold text-plum">Human approval</h2>
          <p className="mt-1 mb-5 text-sm text-plum/60">
            ThirdEye doesn't merge anything on its own. Review the findings and generated tests, then record your decision here.
          </p>
          {decision ? (
            <div className={`flex items-center gap-3 rounded-xl border px-4 py-3.5 ${
              decision === 'approved' ? 'border-plum/20 bg-plum-50 text-plum'
              : decision === 'changes' ? 'border-terracotta/25 bg-terracotta-soft/40 text-terracotta-deep'
              : 'border-coral/25 bg-coral-soft/50 text-coral-deep'}`}>
              {decision === 'approved' && <ThumbsUp size={16} />}
              {decision === 'changes'  && <MessageSquareWarning size={16} />}
              {decision === 'blocked'  && <Ban size={16} />}
              <span className="text-sm font-medium">
                {decision === 'approved' && 'Approved. This is ready to merge.'}
                {decision === 'changes'  && 'Sent back for changes. The author has been notified.'}
                {decision === 'blocked'  && 'Blocked. This cannot merge until the critical finding is resolved.'}
              </span>
              <button onClick={() => setDecision(null)} className="ml-auto text-xs font-medium underline underline-offset-2 opacity-70 hover:opacity-100">Undo</button>
            </div>
          ) : (
            <div className="flex flex-wrap gap-3">
              <Button variant="primary" icon={ThumbsUp}            onClick={() => setDecision('approved')}>Approve</Button>
              <Button variant="outline" icon={MessageSquareWarning} onClick={() => setDecision('changes')}>Request changes</Button>
              <Button variant="ghost"   icon={Ban}                  onClick={() => setDecision('blocked')}>Block merge</Button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { Outlet } from 'react-router-dom'
import Sidebar from '../components/Sidebar'
import Topbar from '../components/Topbar'
import { getProjects } from '../services/api/projects'

export default function Dashboard() {
    const [collapsed, setCollapsed] = useState(false)
    const [projects, setProjects] = useState([])
    const [activeProject, setActiveProject] = useState(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState('')

    useEffect(() => {
        async function fetchProjects() {
            try {
                const data = await getProjects()

                setProjects(data)

                if (data.length > 0) {
                    setActiveProject(data[0])
                }
            } catch (err) {
                setError(err.message || 'Failed to load projects')
            } finally {
                setLoading(false)
            }
        }

        fetchProjects()
    }, [])

    if (loading) {
        return (
            <div className="flex h-screen items-center justify-center bg-ivory-100">
                Loading projects...
            </div>
        )
    }

    if (error) {
        return (
            <div className="flex h-screen items-center justify-center bg-ivory-100">
                <p className="text-red-600">
                    Could not load projects: {error}
                </p>
            </div>
        )
    }

    if (!activeProject) {
        return (
            <div className="flex h-screen items-center justify-center bg-ivory-100">
                No projects found. Please add a project first.
            </div>
        )
    }

    return (
        <div className="flex h-screen w-full overflow-hidden bg-ivory-100">
            <Sidebar
                collapsed={collapsed}
                onToggle={() => setCollapsed((c) => !c)}
            />

            <div className="flex flex-1 flex-col overflow-hidden">
                <Topbar
                    projects={projects}
                    activeProject={activeProject}
                    setActiveProject={setActiveProject}
                />

                <main className="flex-1 overflow-y-auto px-6 py-7 md:px-9">
                    <Outlet context={{ activeProject }} />
                </main>
            </div>
        </div>
    )
}

import { useState, useEffect } from 'react'
import { useOutletContext } from 'react-router-dom'
import { FileCode2, Plus, Minus, FilePlus } from 'lucide-react'
import { createReview, getReviewsByProject } from '../services/api/reviews'

const lineStyle = {
  add: 'bg-plum-50/70 border-l-2 border-plum/40',
  del: 'bg-terracotta-soft/40 border-l-2 border-terracotta/50',
  context: 'border-l-2 border-transparent',
}

const marker = { add: '+', del: '�^'', context: '' }
const markerColor = {
  add: 'text-plum',
  del: 'text-terracotta-deep',
  context: 'text-plum/25',
}

export default function CodeDiff() {
  const { activeProject } = useOutletContext()

  const [reviews, setReviews] = useState([])
  const [selectedReview, setSelectedReview] = useState(null)
  const [selected, setSelected] = useState('')
  const [title, setTitle] = useState('')
  const [codeDiff, setCodeDiff] = useState('')
  const [loading, setLoading] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')

  useEffect(() => {
    if (!activeProject?.id) return

    const loadReviews = async () => {
      setLoading(true)
      setError('')
      setSelectedReview(null)
      setSelected('')
      setSuccess('')

      try {
        const data = await getReviewsByProject(activeProject.id)
        setReviews(data)

        if (data.length > 0) {
          setSelectedReview(data[0])
          setSelected(data[0].title)
          setTitle(data[0].title)
          setCodeDiff(data[0].codeDiff || '')
        } else {
          setTitle('')
          setCodeDiff('')
        }
      } catch (err) {
        setError(err.message || 'Failed to load reviews')
      } finally {
        setLoading(false)
      }
    }

    loadReviews()
  }, [activeProject?.id])

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!activeProject?.id || !title.trim() || !codeDiff.trim()) {
      setError('Please enter a review title and code diff.')
      return
    }

    setSubmitting(true)
    setError('')
    setSuccess('')

    try {
      const review = await createReview(activeProject.id, {
        title: title.trim(),
        codeDiff,
        filesChanged: 1,
        linesAdded: codeDiff.split('\n').filter(line => line.startsWith('+') && !line.startsWith('+++')).length,
        linesRemoved: codeDiff.split('\n').filter(line => line.startsWith('-') && !line.startsWith('---')).length,
        commits: 1,
      })

      setReviews(prev => [review, ...prev])
      setSelectedReview(review)
      setSelected(review.title)
      setSuccess(`Review created successfully. Review ID: ${review.id}`)
    } catch (err) {
      setError(err.message || 'Failed to create review')
    } finally {
      setSubmitting(false)
    }
  }

  if (!activeProject) {
    return <p className="text-plum/60">Select a project to continue.</p>
  }

  return (
      <div className="mx-auto flex max-w-6xl flex-col gap-6">
        <div>
          <h1 className="font-serif text-2xl font-semibold text-plum">
            Code diff
          </h1>
          <p className="mt-1 text-sm text-plum/60">
            {activeProject.name}
          </p>
        </div>

        <form
            onSubmit={handleSubmit}
            className="flex flex-col gap-4 rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft"
        >
          <h2 className="font-serif text-lg font-semibold text-plum">
            Submit code for review
          </h2>

          <input
              value={title}
              onChange={e => setTitle(e.target.value)}
              placeholder="Review title"
              className="rounded-lg border border-sand-line bg-ivory px-4 py-3 text-sm text-plum outline-none focus:border-plum/40"
              required
          />

          <textarea
              value={codeDiff}
              onChange={e => setCodeDiff(e.target.value)}
              placeholder="Paste your code diff here..."
              rows={10}
              className="w-full resize-y rounded-lg border border-sand-line bg-ivory px-4 py-3 font-mono text-sm text-plum outline-none focus:border-plum/40"
              required
          />

          <button
              type="submit"
              disabled={submitting}
              className="w-fit rounded-lg bg-plum px-5 py-2.5 text-sm font-medium text-white transition-opacity hover:opacity-90 disabled:opacity-50"
          >
            {submitting ? 'Submitting...' : 'Submit for review'}
          </button>

          {error && (
              <p className="text-sm text-terracotta-deep">{error}</p>
          )}

          {success && (
              <p className="text-sm text-plum">{success}</p>
          )}
        </form>

        <div className="grid grid-cols-1 gap-6 lg:grid-cols-[280px_1fr]">
          <div className="h-fit overflow-hidden rounded-xl2 border border-sand-line bg-ivory-card shadow-soft">
            <div className="border-b border-sand-line px-4 py-3 text-xs font-medium text-plum/50">
              Reviews
            </div>

            {loading ? (
                <p className="p-4 text-sm text-plum/60">Loading reviews...</p>
            ) : reviews.length === 0 ? (
                <p className="p-4 text-sm text-plum/60">
                  No reviews yet. Submit a code diff to get started.
                </p>
            ) : (
                <div className="flex flex-col">
                  {reviews.map(review => (
                      <button
                          key={review.id}
                          onClick={() => {
                            setSelectedReview(review)
                            setSelected(review.title)
                            setTitle(review.title)
                            setCodeDiff(review.codeDiff || '')
                            setSuccess('')
                            setError('')
                          }}
                          className={`flex items-center gap-2.5 border-b border-sand-line/70 px-4 py-3 text-left transition-colors last:border-b-0 ${
                              selectedReview?.id === review.id
                                  ? 'bg-sand/50'
                                  : 'hover:bg-sand/25'
                          }`}
                      >
                        <FileCode2
                            size={15}
                            className="shrink-0 text-plum/50"
                        />

                        <span className="min-w-0 flex-1 truncate text-xs text-plum">
                    {review.title}
                  </span>

                        <span className="text-[10px] text-plum/50">
                    #{review.id}
                  </span>
                      </button>
                  ))}
                </div>
            )}
          </div>

          <div className="overflow-hidden rounded-xl2 border border-sand-line bg-ivory-card shadow-soft">
            <div className="flex items-center justify-between border-b border-sand-line bg-peach-soft/60 px-5 py-3">
            <span className="font-mono text-sm text-plum">
              {selected || 'No review selected'}
            </span>

              {selectedReview && (
                  <span className="rounded-full bg-sand px-3 py-1 text-xs text-plum">
                {selectedReview.status}
              </span>
              )}
            </div>

            {selectedReview ? (
                <div className="overflow-x-auto">
                  <table className="w-full border-collapse font-mono text-[13px]">
                    <tbody>
                    {selectedReview.codeDiff
                        ?.split('\n')
                        .map((text, i) => {
                          const type = text.startsWith('+')
                              ? 'add'
                              : text.startsWith('-')
                                  ? 'del'
                                  : 'context'

                          return (
                              <tr key={i} className={lineStyle[type]}>
                                <td className="w-10 select-none px-2 py-0.5 text-right text-plum/30">
                                  {type === 'del' ? i + 1 : ''}
                                </td>

                                <td className="w-10 select-none px-2 py-0.5 text-right text-plum/30">
                                  {type === 'add' ? i + 1 : ''}
                                </td>

                                <td className={`w-5 select-none py-0.5 text-center font-semibold ${markerColor[type]}`}>
                                  {marker[type]}
                                </td>

                                <td className="whitespace-pre px-3 py-0.5 text-plum/90">
                                  {text || '\u00A0'}
                                </td>
                              </tr>
                          )
                        })}
                    </tbody>
                  </table>
                </div>
            ) : (
                <div className="p-6 text-sm text-plum/50">
                  Submit a code diff or select an existing review.
                </div>
            )}
          </div>
        </div>
      </div>
  )
}

import { useState, useMemo, useEffect } from 'react'
import { ChevronDown, Lightbulb } from 'lucide-react'
import { useOutletContext } from 'react-router-dom'
import SeverityBadge from '../components/SeverityBadge'
import { getReviewsByProject } from '../services/api/reviews'
import { getFindingsByReview } from '../services/api/findings'

const severityOrder = ['critical', 'high', 'medium', 'low']
const categories = ['All', 'Security', 'Quality', 'Style']

const severityBorder = {
    critical: 'border-l-coral',
    high: 'border-l-terracotta',
    medium: 'border-l-sand-line',
    low: 'border-l-sand-line',
}

export default function Findings() {
    const { activeProject } = useOutletContext()
    const [reviews, setReviews] = useState([])
    const [selectedReviewId, setSelectedReviewId] = useState('')
    const [findings, setFindings] = useState([])
    const [severityFilter, setSeverityFilter] = useState('all')
    const [category, setCategory] = useState('All')
    const [expanded, setExpanded] = useState(null)
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState('')

    useEffect(() => {
        if (!activeProject?.id) return

        const loadReviews = async () => {
            try {
                setLoading(true)
                setError('')
                setFindings([])
                setSelectedReviewId('')

                const data = await getReviewsByProject(activeProject.id)
                setReviews(data)

                if (data.length > 0) {
                    setSelectedReviewId(String(data[0].id))
                }
            } catch (err) {
                setError(err.message || 'Failed to load reviews')
            } finally {
                setLoading(false)
            }
        }

        loadReviews()
    }, [activeProject?.id])

    useEffect(() => {
        if (!selectedReviewId) {
            setFindings([])
            return
        }

        const loadFindings = async () => {
            try {
                setLoading(true)
                setError('')

                const data = await getFindingsByReview(selectedReviewId)
                setFindings(data)
                setExpanded(data.length > 0 ? data[0].id : null)
            } catch (err) {
                setError(err.message || 'Failed to load findings')
                setFindings([])
            } finally {
                setLoading(false)
            }
        }

        loadFindings()
    }, [selectedReviewId])

    const severityCounts = useMemo(
        () =>
            findings.reduce(
                (counts, finding) => {
                    const severity = finding.severity?.toLowerCase()
                    counts[severity] = (counts[severity] || 0) + 1
                    return counts
                },
                {}
            ),
        [findings]
    )

    const filtered = useMemo(
        () =>
            findings.filter(
                (f) =>
                    (severityFilter === 'all' ||
                        f.severity?.toLowerCase() === severityFilter) &&
                    (category === 'All' ||
                        f.category?.toLowerCase() === category.toLowerCase())
            ),
        [findings, severityFilter, category]
    )

    return (
        <div className="mx-auto flex max-w-4xl flex-col gap-6">
            <div>
                <h1 className="font-serif text-2xl font-semibold text-plum">
                    Findings
                </h1>
                <p className="mt-1 text-sm text-plum/60">
                    {findings.length} issues found across the changeset
                </p>
            </div>

            {reviews.length > 0 && (
                <div>
                    <label className="mb-2 block text-sm font-medium text-plum">
                        Select review
                    </label>
                    <select
                        value={selectedReviewId}
                        onChange={(e) => setSelectedReviewId(e.target.value)}
                        className="w-full rounded-xl border border-sand-line bg-ivory-card px-4 py-3 text-sm text-plum focus:outline-none"
                    >
                        {reviews.map((review) => (
                            <option key={review.id} value={String(review.id)}>
                                {review.title}
                            </option>
                        ))}
                    </select>
                </div>
            )}

            <div className="flex flex-wrap items-center gap-2.5">
                <button
                    onClick={() => setSeverityFilter('all')}
                    className={`rounded-full border px-3.5 py-1.5 text-sm font-medium transition-colors ${
                        severityFilter === 'all'
                            ? 'border-plum bg-plum text-ivory-100'
                            : 'border-sand-line bg-ivory-card text-plum/60 hover:text-plum'
                    }`}
                >
                    All ({findings.length})
                </button>

                {severityOrder.map((sev) => (
                    <button
                        key={sev}
                        onClick={() => setSeverityFilter(sev)}
                        className={`rounded-full border px-3.5 py-1.5 text-sm font-medium capitalize transition-colors ${
                            severityFilter === sev
                                ? 'border-plum bg-plum text-ivory-100'
                                : 'border-sand-line bg-ivory-card text-plum/60 hover:text-plum'
                        }`}
                    >
                        {sev} ({severityCounts[sev] || 0})
                    </button>
                ))}

                <div className="ml-auto">
                    <select
                        value={category}
                        onChange={(e) => setCategory(e.target.value)}
                        className="rounded-full border border-sand-line bg-ivory-card px-3.5 py-1.5 text-sm font-medium text-plum focus:outline-none"
                    >
                        {categories.map((c) => (
                            <option key={c} value={c}>
                                {c} category
                            </option>
                        ))}
                    </select>
                </div>
            </div>

            {loading && (
                <p className="py-6 text-center text-sm text-plum/60">
                    Loading findings...
                </p>
            )}

            {error && (
                <p className="rounded-lg bg-coral/10 p-4 text-sm text-coral">
                    {error}
                </p>
            )}

            {!loading && !error && reviews.length === 0 && (
                <div className="rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-10 text-center text-sm text-plum/50">
                    No reviews found for this project. Submit a code review first.
                </div>
            )}

            {!loading && !error && reviews.length > 0 && (
                <div className="flex flex-col gap-3">
                    {filtered.map((f) => {
                        const isOpen = expanded === f.id
                        const severity = f.severity?.toLowerCase()

                        return (
                            <div
                                key={f.id}
                                className={`overflow-hidden rounded-xl2 border border-l-4 border-sand-line bg-ivory-card shadow-soft ${
                                    severityBorder[severity] || 'border-l-sand-line'
                                }`}
                            >
                                <button
                                    onClick={() => setExpanded(isOpen ? null : f.id)}
                                    className="flex w-full items-center justify-between gap-4 px-5 py-4 text-left"
                                >
                                    <div className="flex min-w-0 items-center gap-3.5">
                                        <SeverityBadge severity={severity} />
                                        <div className="min-w-0">
                                            <p className="truncate text-sm font-medium text-plum">
                                                {f.title}
                                            </p>
                                            <p className="truncate font-mono text-xs text-plum/50">
                                                {f.file}:{f.line} A� {f.category}
                                            </p>
                                        </div>
                                    </div>

                                    <ChevronDown
                                        size={16}
                                        className={`shrink-0 text-plum/40 transition-transform ${
                                            isOpen ? 'rotate-180' : ''
                                        }`}
                                    />
                                </button>

                                {isOpen && (
                                    <div className="border-t border-sand-line px-5 py-4">
                                        <p className="text-sm leading-relaxed text-plum/75">
                                            {f.description}
                                        </p>

                                        <div className="mt-3 flex items-start gap-2 rounded-lg bg-plum-50 px-3.5 py-3">
                                            <Lightbulb
                                                size={15}
                                                className="mt-0.5 shrink-0 text-plum/60"
                                            />
                                            <p className="text-sm leading-relaxed text-plum/80">
                                                {f.suggestion}
                                            </p>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )
                    })}

                    {filtered.length === 0 && (
                        <div className="rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-10 text-center text-sm text-plum/50">
                            No findings match these filters.
                        </div>
                    )}
                </div>
            )}
        </div>
    )
}

import { useState, useEffect, useCallback } from 'react'
import { useOutletContext } from 'react-router-dom'
import { Download, ShieldCheck, Loader2 } from 'lucide-react'
import Button from '../components/Button'
import ProgressRing from '../components/ProgressRing'
import SeverityBadge from '../components/SeverityBadge'
import { getReviewsByProject } from '../services/api/reviews'
import { getFindingsByReview } from '../services/api/findings'
import { apiRequest } from '../services/api/client'

export default function Report() {
  const { activeProject } = useOutletContext()

  const [review,   setReview]   = useState(null)
  const [findings, setFindings] = useState([])
  const [summary,  setSummary]  = useState(null)
  const [loading,  setLoading]  = useState(true)
  const [error,    setError]    = useState('')

  const loadData = useCallback(async () => {
    if (!activeProject?.id) return
    try {
      const reviews = await getReviewsByProject(activeProject.id)
      if (!reviews || reviews.length === 0) { setLoading(false); return }

      const latest = reviews.reduce((a, b) => (a.id > b.id ? a : b))
      setReview(latest)

      if (latest.status === 'COMPLETED') {
        const [f, s] = await Promise.all([
          getFindingsByReview(latest.id),
          apiRequest(`/api/reviews/${latest.id}/findings/summary`, { method: 'GET' }),
        ])
        setFindings(f || [])
        setSummary(s)
      }
    } catch (err) {
      setError(err.message || 'Failed to load report data')
    } finally {
      setLoading(false)
    }
  }, [activeProject?.id])

  useEffect(() => {
    setLoading(true); setError(''); setReview(null); setFindings([]); setSummary(null)
    loadData()
  }, [loadData])

  if (loading) return (
    <div className="mx-auto flex max-w-4xl items-center justify-center py-20">
      <Loader2 size={24} className="animate-spin text-plum/40" />
    </div>
  )

  if (error) return (
    <div className="mx-auto max-w-4xl rounded-lg bg-coral/10 p-4 text-sm text-coral">{error}</div>
  )

  if (!review) return (
    <div className="mx-auto max-w-4xl rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-14 text-center text-sm text-plum/50">
      No reviews found for <strong>{activeProject.name}</strong>. Submit a code diff first.
    </div>
  )

  if (review.status !== 'COMPLETED') return (
    <div className="mx-auto max-w-4xl rounded-xl2 border border-sand-line bg-ivory-card p-6 text-sm text-plum/60">
      <p className="font-medium text-plum mb-1">Report not yet available</p>
      Review #{review.id} is currently <strong>{review.status}</strong>.
      The report will be available once analysis completes.
    </div>
  )

  const criticalCount = summary?.critical ?? findings.filter(f => f.severity === 'critical').length
  const highCount     = summary?.high     ?? findings.filter(f => f.severity === 'high').length
  const total         = summary?.total    ?? findings.length
  // Risk score: weighted estimate based on severity counts (demo value, not AI-computed)
  const riskScore = Math.min(100, Math.round(criticalCount * 30 + highCount * 15 + (summary?.medium ?? 0) * 5))

  return (
    <div className="mx-auto flex max-w-4xl flex-col gap-6">

      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="font-serif text-2xl font-semibold text-plum">Final report</h1>
          <p className="mt-1 text-sm text-plum/60">
            {activeProject.name} A� review #{review.id} A� {review.title}
          </p>
        </div>
        <Button variant="outline" icon={Download}>Export PDF</Button>
      </div>

      {/* Summary hero */}
      <div className="rounded-xl2 border border-sand-line bg-plum p-7 text-ivory-100 shadow-lifted">
        <div className="flex flex-wrap items-center gap-8">
          <ProgressRing progress={riskScore} size={104} label={riskScore} sub="risk score" />
          <div className="flex flex-col gap-1.5">
            <span className={`w-fit rounded-full px-3 py-1 text-xs font-medium text-white ${criticalCount > 0 ? 'bg-coral' : 'bg-plum/60'}`}>
              {criticalCount > 0 ? 'Changes required' : 'Approved with notes'}
            </span>
            <h2 className="font-serif text-xl font-semibold">
              {criticalCount > 0
                ? `${criticalCount} critical issue${criticalCount > 1 ? 's' : ''} must be resolved before merging`
                : 'No critical issues �?" review the findings before merging'}
            </h2>
            <p className="max-w-md text-sm text-ivory-100/70">
              {total} finding{total !== 1 ? 's' : ''} across the changeset.
              {criticalCount > 0 && ' Resolve all critical findings first.'}
            </p>
            {/* Risk score is a simple weighted estimate, not AI-computed */}
            <p className="text-xs text-ivory-100/40 mt-1">�s� Risk score is a demo estimate �?" not AI-computed</p>
          </div>
        </div>
      </div>

      {/* Stats grid */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <div className="rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft">
          <p className="text-xs font-medium text-plum/50">Findings</p>
          <p className="mt-2 font-serif text-2xl font-semibold text-plum">{total}</p>
          <div className="mt-2 flex flex-wrap gap-1.5">
            {[['critical', criticalCount], ['high', highCount], ['medium', summary?.medium ?? 0], ['low', summary?.low ?? 0]].map(([sev, count]) =>
              count > 0 ? <span key={sev} className="text-[11px] font-medium text-plum/50">{count} {sev}</span> : null
            )}
          </div>
        </div>
        <div className="rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft">
          <p className="text-xs font-medium text-plum/50">Files changed</p>
          <p className="mt-2 font-serif text-2xl font-semibold text-plum">{review.filesChanged}</p>
        </div>
        <div className="rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft">
          <p className="text-xs font-medium text-plum/50">Lines added</p>
          <p className="mt-2 font-serif text-2xl font-semibold text-terracotta-deep">+{review.linesAdded}</p>
        </div>
        <div className="rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft">
          <p className="text-xs font-medium text-plum/50">Lines removed</p>
          <p className="mt-2 font-serif text-2xl font-semibold text-plum">�^'{review.linesRemoved}</p>
        </div>
      </div>

      {/* Findings list */}
      <div className="rounded-xl2 border border-sand-line bg-ivory-card p-6 shadow-soft">
        <h2 className="mb-4 font-serif text-lg font-semibold text-plum">Findings summary</h2>
        {findings.length === 0
          ? <p className="text-sm text-plum/50">No findings for this review.</p>
          : <div className="flex flex-col divide-y divide-sand-line">
              {findings.map(f => (
                <div key={f.id} className="flex items-center justify-between gap-4 py-3">
                  <div className="flex items-center gap-3">
                    <SeverityBadge severity={f.severity} />
                    <span className="text-sm text-plum">{f.title}</span>
                  </div>
                  <span className="font-mono text-xs text-plum/45">{f.file?.split('/').pop()}</span>
                </div>
              ))}
            </div>
        }
      </div>

      {/* Footer note */}
      <div className="flex items-center gap-3 rounded-xl2 border border-sand-line bg-peach-soft px-6 py-4 shadow-soft">
        <ShieldCheck size={18} className="shrink-0 text-terracotta-deep" />
        <p className="text-sm text-plum/75">
          Analysis by <span className="font-medium text-plum">ThirdEye AI</span> (mock engine).
          Generated tests, coverage delta, and approver are not yet available �?" these require the IBM Granite integration.
        </p>
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { CheckCircle2, XCircle, Clock, Play, Loader2, Code } from 'lucide-react'
import { useOutletContext } from 'react-router-dom'
import Button from '../components/Button'
import StatCard from '../components/StatCard'
import { getReviewsByProject } from '../services/api/reviews'
import { getTests, generateTests } from '../services/api/tests'

const statusMeta = {
  PASSED:  { icon: CheckCircle2, color: 'text-plum',      label: 'Passed'  },
  FAILED:  { icon: XCircle,      color: 'text-coral-deep', label: 'Failed'  },
  PENDING: { icon: Clock,        color: 'text-plum/40',    label: 'Pending' },
  // normalise lowercase values from mockData if still in use
  passed:  { icon: CheckCircle2, color: 'text-plum',      label: 'Passed'  },
  failed:  { icon: XCircle,      color: 'text-coral-deep', label: 'Failed'  },
  pending: { icon: Clock,        color: 'text-plum/40',    label: 'Pending' },
}
const tabs = ['All', 'Passed', 'Failed', 'Pending']

export default function Tests() {
  const { activeProject } = useOutletContext()

  const [review,      setReview]      = useState(null)
  const [tests,       setTests]       = useState([])
  const [tab,         setTab]         = useState('All')
  const [loading,     setLoading]     = useState(true)
  const [generating,  setGenerating]  = useState(false)
  const [error,       setError]       = useState('')
  const [genError,    setGenError]    = useState('')

  const loadReviewAndTests = useCallback(async () => {
    if (!activeProject?.id) return
    try {
      setLoading(true); setError('')
      const reviews = await getReviewsByProject(activeProject.id)
      if (!reviews || reviews.length === 0) { setLoading(false); return }
      const latest = reviews.reduce((a, b) => (a.id > b.id ? a : b))
      setReview(latest)
      if (latest.status === 'COMPLETED') {
        const t = await getTests(latest.id)
        setTests(t || [])
      }
    } catch (err) {
      setError(err.message || 'Failed to load tests')
    } finally {
      setLoading(false)
    }
  }, [activeProject?.id])

  useEffect(() => { loadReviewAndTests() }, [loadReviewAndTests])

  const handleGenerate = async () => {
    if (!review) return
    setGenerating(true); setGenError('')
    try {
      const t = await generateTests(review.id)
      setTests(t || [])
    } catch (err) {
      setGenError(err.message || 'Failed to generate tests')
    } finally {
      setGenerating(false)
    }
  }

  const normaliseStatus = (s) => (s ?? 'pending').toUpperCase()

  const filtered = tab === 'All'
    ? tests
    : tests.filter(t => normaliseStatus(t.status) === tab.toUpperCase())

  const counts = tests.reduce((acc, t) => {
    const s = normaliseStatus(t.status)
    acc[s] = (acc[s] || 0) + 1
    return acc
  }, {})

  if (loading) return (
    <div className="mx-auto flex max-w-4xl items-center justify-center py-20">
      <Loader2 size={24} className="animate-spin text-plum/40" />
    </div>
  )

  if (error) return (
    <div className="mx-auto max-w-4xl rounded-lg bg-coral/10 p-4 text-sm text-coral">{error}</div>
  )

  const canGenerate = review?.status === 'COMPLETED'

  return (
    <div className="mx-auto flex max-w-4xl flex-col gap-6">

      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="font-serif text-2xl font-semibold text-plum">Generated tests</h1>
          <p className="mt-1 text-sm text-plum/60">
            {tests.length > 0
              ? `${tests.length} test stubs generated for ${activeProject.name}`
              : `No tests generated yet for ${activeProject.name}`}
          </p>
        </div>
        <Button
          variant="outline"
          icon={Play}
          onClick={handleGenerate}
          disabled={!canGenerate || generating}
        >
          {generating ? 'Generating�?�' : tests.length > 0 ? 'Re-generate' : 'Generate tests'}
        </Button>
      </div>

      {/* Mock disclaimer */}
      <div className="flex items-start gap-3 rounded-xl border border-sand-line bg-peach-soft px-4 py-3 text-sm text-plum/70">
        <Code size={16} className="mt-0.5 shrink-0 text-terracotta-deep" />
        <span>
          <strong className="text-plum">Simulated test generation</strong> �?" these are template stubs
          derived from findings, not AI-written tests. They are never executed.
          Real IBM Granite test generation will replace this in the next milestone.
        </span>
      </div>

      {genError && (
        <p className="rounded-lg bg-coral/10 p-3 text-sm text-coral">{genError}</p>
      )}

      {!review && (
        <div className="rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-10 text-center text-sm text-plum/50">
          No reviews found. Submit a code diff first.
        </div>
      )}

      {review && review.status !== 'COMPLETED' && (
        <div className="rounded-xl2 border border-sand-line bg-ivory-card px-5 py-8 text-center text-sm text-plum/50">
          Review #{review.id} is <strong>{review.status}</strong>. Tests can be generated once analysis completes.
        </div>
      )}

      {canGenerate && tests.length === 0 && !generating && (
        <div className="rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-10 text-center text-sm text-plum/50">
          No tests generated yet. Click <strong>Generate tests</strong> to create stubs from the findings.
        </div>
      )}

      {tests.length > 0 && (
        <>
          <div className="grid grid-cols-3 gap-4">
            <StatCard label="Passed"  value={counts.PASSED  || 0} accent="plum"       />
            <StatCard label="Failed"  value={counts.FAILED  || 0} accent="coral"      />
            <StatCard label="Pending" value={counts.PENDING || 0} accent="terracotta" />
          </div>

          <div className="flex gap-1 rounded-xl border border-sand-line bg-ivory-card p-1 w-fit shadow-soft">
            {tabs.map(t => (
              <button key={t} onClick={() => setTab(t)}
                className={`rounded-lg px-4 py-1.5 text-sm font-medium transition-colors ${
                  tab === t ? 'bg-plum text-ivory-100' : 'text-plum/55 hover:text-plum'}`}>
                {t}
              </button>
            ))}
          </div>

          <div className="flex flex-col gap-3">
            {filtered.map(t => {
              const status = normaliseStatus(t.status)
              const meta   = statusMeta[status] ?? statusMeta.PENDING
              const Icon   = meta.icon
              return (
                <div key={t.id}
                  className="rounded-xl2 border border-sand-line bg-ivory-card px-5 py-4 shadow-soft">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex items-start gap-3">
                      <Icon size={18} className={`mt-0.5 shrink-0 ${meta.color}`} />
                      <div>
                        <p className="text-sm font-medium text-plum">{t.name}</p>
                        <p className="mt-1 font-mono text-xs text-plum/50">{t.file}</p>
                      </div>
                    </div>
                    <span className="shrink-0 rounded-full bg-sand px-2 py-0.5 text-[10px] text-plum/50">
                      mock stub
                    </span>
                  </div>
                  {t.linkedFindingId && (
                    <div className="mt-2 ml-8 text-xs text-plum/45">
                      Covers finding <span className="font-mono">#{t.linkedFindingId}</span>
                    </div>
                  )}
                  {t.testCode && (
                    <details className="mt-3 ml-8">
                      <summary className="cursor-pointer text-xs font-medium text-plum/50 hover:text-plum">
                        View generated code
                      </summary>
                      <pre className="mt-2 overflow-x-auto rounded-lg bg-plum-50 p-3 font-mono text-xs text-plum/80 whitespace-pre-wrap">
                        {t.testCode}
                      </pre>
                    </details>
                  )}
                </div>
              )
            })}
            {filtered.length === 0 && (
              <div className="rounded-xl2 border border-dashed border-sand-line bg-ivory-card px-5 py-10 text-center text-sm text-plum/50">
                No tests match this filter.
              </div>
            )}
          </div>
        </>
      )}
    </div>
  )
}

const styles = {
  critical: 'bg-coral-soft text-coral-deep border-coral/30',
  high: 'bg-terracotta-soft text-terracotta-deep border-terracotta/30',
  medium: 'bg-sand text-plum border-sand-line',
  low: 'bg-ivory-200 text-plum/70 border-sand-line',
}

const labels = {
  critical: 'Critical',
  high: 'High',
  medium: 'Medium',
  low: 'Low',
}

export default function SeverityBadge({ severity, size = 'sm' }) {
  const pad = size === 'sm' ? 'px-2.5 py-1 text-xs' : 'px-3 py-1.5 text-sm'
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full border font-medium ${pad} ${styles[severity]}`}
    >
      <span className="h-1.5 w-1.5 rounded-full bg-current" />
      {labels[severity]}
    </span>
  )
}
export default function StatCard({ label, value, sub, accent = 'plum' }) {
  const accents = {
    plum: 'text-plum',
    coral: 'text-coral-deep',
    terracotta: 'text-terracotta-deep',
  }
  return (
    <div className="rounded-xl2 border border-sand-line bg-ivory-card p-5 shadow-soft">
      <p className="text-xs font-medium text-plum/50">{label}</p>
      <p className={`mt-2 font-serif text-2xl font-semibold ${accents[accent]}`}>{value}</p>
      {sub && <p className="mt-1 text-xs text-plum/45">{sub}</p>}
    </div>
  )
}
export default function ProgressRing({ progress = 0, size = 96, stroke = 8, label, sub }) {
  const radius = (size - stroke) / 2
  const circumference = 2 * Math.PI * radius
  const offset = circumference - (progress / 100) * circumference

  return (
    <div className="relative inline-flex items-center justify-center" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="#EFE1C6"
          strokeWidth={stroke}
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="#33233F"
          strokeWidth={stroke}
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          style={{ transition: 'stroke-dashoffset 0.6s ease' }}
        />
      </svg>
      <div className="absolute flex flex-col items-center">
        <span className="font-serif text-xl font-semibold text-plum">{label ?? `${progress}%`}</span>
        {sub && <span className="text-[11px] text-plum/60">{sub}</span>}
      </div>
    </div>
  )
}
const variants = {
  primary:
    'bg-plum text-ivory-card hover:bg-plum-light active:bg-plum-deep shadow-soft',
  coral:
    'bg-coral text-white hover:bg-coral-deep shadow-soft',
  outline:
    'bg-transparent text-plum border border-sand-line hover:bg-sand/60',
  ghost:
    'bg-transparent text-plum/70 hover:bg-sand/50 hover:text-plum',
}

const sizes = {
  sm: 'px-3 py-1.5 text-sm rounded-lg',
  md: 'px-4 py-2.5 text-sm rounded-xl',
  lg: 'px-6 py-3.5 text-base rounded-xl',
}

export default function Button({
  children,
  variant = 'primary',
  size = 'md',
  icon: Icon,
  className = '',
  ...props
}) {
  return (
    <button
      className={`inline-flex items-center justify-center gap-2 font-medium transition-colors duration-150 disabled:opacity-50 disabled:cursor-not-allowed ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {Icon && <Icon size={16} strokeWidth={2} />}
      {children}
    </button>
  )
}

import { NavLink } from 'react-router-dom'
import {
