export const getReviewsByProject = (projectId) =>
    apiRequest(`/api/projects/${projectId}/reviews`, {
        method: 'GET'
    })

export const getReviewById = (reviewId) =>
    apiRequest(`/api/reviews/${reviewId}`, {
        method: 'GET'
    })

