    apiRequest(`/api/projects/${projectId}/reviews`, {
        method: 'POST',
        body: review
    })

export const getReviewDiff = (reviewId) =>
    apiRequest(`/api/reviews/${reviewId}/diff`, {
        method: 'GET'
    })

