307 |     /**
308 |      * Attempts to extract the nearest diff file header above line {@code lineIndex}.
309 |      * Returns "unknown" when no header is found.
310 |      */
311 |     private String guessFile(String diff, int lineIndex) {
312 |         String[] lines = diff.split("\n");
313 |         for (int i = lineIndex; i >= 0; i--) {
314 |             String l = lines[i];
315 |             if (l.startsWith("+++ ")) {
316 |                 return l.replace("+++ b/", "").replace("+++ ", "").trim();
317 |             }
318 |             if (l.startsWith("--- ")) {
319 |                 return l.replace("--- a/", "").replace("--- ", "").trim();
320 |             }
321 |         }
322 |         return "unknown";
323 |     }
324 | }
