46 |     /** 400 – illegal arguments */
47 |     @ExceptionHandler(IllegalArgumentException.class)
48 |     public ResponseEntity<Map<String, Object>> handleIllegalArg(IllegalArgumentException ex) {
49 |         return build(HttpStatus.BAD_REQUEST, ex.getMessage());
50 |     }
51 | 
52 |     /** 500 – unexpected errors (message only, no stack trace) */
53 |     @ExceptionHandler(Exception.class)
54 |     public ResponseEntity<Map<String, Object>> handleGeneric(Exception ex) {
55 |         return build(HttpStatus.INTERNAL_SERVER_ERROR,
56 |                 "An unexpected error occurred. Please try again later.");
57 |     }
58 | 
59 |     // ── helpers ──────────────────────────────────────────────────────────────
60 | 
61 |     private ResponseEntity<Map<String, Object>> build(HttpStatus status, String message) {
