    private static Finding toEntity(Review review, RuleFinding rf) {
        return new Finding(
                review,
                rf.getTitle(),
                rf.getSeverity(),
                rf.getCategory(),
                rf.getFile(),
                rf.getLine(),
                rf.getDescription(),
                rf.getSuggestion()
        );
    }

