        Review review = reviewRepository.findById(reviewId).orElse(null);
        if (review == null) {
            log.warn("[MOCK] Review {} not found – skipping analysis", reviewId);
            return;
        }

        try {
            // Step 1 — mark as ANALYZING
            review.setStatus("ANALYZING");
            review.setProgress(10);
            reviewRepository.save(review);

            // Step 2 — remove stale findings so re-runs don't duplicate
            findingRepository.deleteByReview_Id(reviewId);

            // Step 3 — build findings from diff patterns
            String diff = review.getCodeDiff() == null ? "" : review.getCodeDiff();
            List<Finding> findings = buildFindings(review, diff);

            // Step 4 — progress update after scan
            review.setProgress(70);
            reviewRepository.save(review);

            // Step 5 — persist findings
            findingRepository.saveAll(findings);

            // Step 6 — mark COMPLETED
            review.setStatus("COMPLETED");
            review.setProgress(100);
            reviewRepository.save(review);

            log.info("[MOCK] Completed mock analysis for review {} — {} findings", reviewId, findings.size());

        } catch (Exception ex) {
            log.error("[MOCK] Analysis failed for review {}: {}", reviewId, ex.getMessage(), ex);
            try {
                review.setStatus("FAILED");
                reviewRepository.save(review);
            } catch (Exception saveEx) {
                log.error("[MOCK] Could not persist FAILED status for review {}", reviewId, saveEx);
            }
