                        "security",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] The diff contains SQL built by string concatenation with user-controlled input. " +
                        "This is a classic SQL injection vector.",
                        "Use parameterised queries or a prepared statement. " +
                        "Spring Data JPA query methods and @Query with :param placeholders are safe alternatives."
                ));
            }

            // ── Quality: TODO / FIXME left in code ───────────────────────────
            if (containsTodoFixme(line)) {
                findings.add(new Finding(
                        review,
                        "TODO / FIXME left in submitted code",
                        "low",
                        "quality",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] A TODO or FIXME comment was found in a newly added line. " +
                        "Unresolved annotations indicate incomplete implementation.",
                        "Resolve the TODO before merging. If work is deferred, create a tracked issue instead."
                ));
            }

            // ── Bugs: empty catch block ───────────────────────────────────────
            if (containsEmptyCatch(line)) {
                findings.add(new Finding(
                        review,
                        "Exception silently swallowed in catch block",
                        "medium",
                        "bugs",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] A catch block appears to swallow exceptions without logging or rethrowing. " +
                        "This hides failures and makes debugging very difficult.",
                        "At minimum, log the exception (log.error(\"...\", ex)). " +
                        "Consider whether the exception should propagate to the caller."
                ));
            }

            // ── Bugs: Optional.get() without isPresent ────────────────────────
            if (containsOptionalGetWithoutCheck(line)) {
                findings.add(new Finding(
                        review,
                        "Optional.get() called without presence check",
                        "high",
                        "bugs",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] Optional.get() is called without a preceding isPresent() or orElse() guard. " +
                        "This will throw NoSuchElementException at runtime when the value is absent.",
                        "Use optional.orElseThrow(() -> new ResourceNotFoundException(...)) or " +
                        "optional.ifPresent(...) to handle the empty case safely."
                ));
            }
        }

        // ── Coverage: no tests in diff ────────────────────────────────────────
        boolean hasTestChanges = diff.contains("@Test") || diff.contains("test") || diff.contains("Test");
        if (!hasTestChanges) {
            findings.add(new Finding(
                    review,
                    "No test changes detected in diff",
                    "medium",
                    "coverage",
                    "unknown",
                    0,
                    "[MOCK] The submitted diff does not appear to include any test file changes. " +
                    "Adding or updating tests alongside feature code maintains coverage.",
                    "Add unit or integration tests that exercise the changed code paths. " +
                    "Aim for at least one happy-path and one error-path test per new method."
            ));
        }

        // ── Quality: large diff warning ───────────────────────────────────────
        long addedLines = java.util.Arrays.stream(lines)
                .filter(l -> l.startsWith("+") && !l.startsWith("+++"))
                .count();
        if (addedLines > 200) {
            findings.add(new Finding(
                    review,
                    "Large changeset — consider splitting",
                    "low",
                    "quality",
                    "unknown",
                    0,
                    "[MOCK] The diff adds more than 200 lines. Large pull requests are harder to review " +
                    "thoroughly and statistically introduce more defects.",
                    "Split this change into smaller, independently reviewable pull requests " +
                    "focused on a single concern."
            ));
        }

        return findings;
    }

    // ── Pattern helpers ───────────────────────────────────────────────────────

    private boolean containsCredentialPattern(String line) {
        String lower = line.toLowerCase();
        return (lower.contains("password") || lower.contains("passwd") ||
                lower.contains("secret") || lower.contains("apikey") ||
                lower.contains("api_key") || lower.contains("token"))
               && (line.contains("=") || line.contains(":"))
               && (line.contains("\"") || line.contains("'"));
    }

    private boolean containsSqlConcatPattern(String line) {
        String lower = line.toLowerCase();
        return lower.contains("select") && lower.contains("+") &&
               (lower.contains("where") || lower.contains("from"));
    }

    private boolean containsTodoFixme(String line) {
        String upper = line.toUpperCase();
        return upper.contains("TODO") || upper.contains("FIXME") || upper.contains("HACK");
    }

    private boolean containsEmptyCatch(String line) {
        // Matches: "} catch" with nothing meaningful after it on the same line
        return line.matches(".*}\\s*catch\\s*\\(.*\\)\\s*\\{?\\s*") ||
               line.matches(".*catch\\s*\\(.*\\)\\s*\\{\\s*}.*");
    }

    private boolean containsOptionalGetWithoutCheck(String line) {
        return line.contains(".get()") && !line.contains("isPresent") &&
               !line.contains("orElse") && !line.contains("ifPresent");
    }

    /**
     * Attempts to extract the nearest diff file header above line {@code lineIndex}.
     * Returns "unknown" when no header is found.
     */
    private String guessFile(String diff, int lineIndex) {
        String[] lines = diff.split("\n");
        for (int i = lineIndex; i >= 0; i--) {
            String l = lines[i];
            if (l.startsWith("+++ ")) {
                return l.replace("+++ b/", "").replace("+++ ", "").trim();
            }
            if (l.startsWith("--- ")) {
                return l.replace("--- a/", "").replace("--- ", "").trim();
            }
        }
        return "unknown";
    }
