     * Execution status of this test.
     * Values: PASSED | FAILED | PENDING
     * Tests generated by the mock engine are always PENDING (never actually run).
     */
    private String status = "PENDING";

    /** Duration string, e.g. "14ms". Null for pending tests. */
    private String duration;

    /** Optional reference to a Finding id that this test covers. */
    private String linkedFindingId;

    /** The generated test source code (simple template). */
    @Column(length = 10000)
    private String testCode;

    public GeneratedTest() {}

    public GeneratedTest(Review review, String name, String file,
                         String status, String duration,
                         String linkedFindingId, String testCode) {
        this.review = review;
        this.name = name;
        this.file = file;
        this.status = status;
        this.duration = duration;
        this.linkedFindingId = linkedFindingId;
        this.testCode = testCode;
    }

    public Long getId()                  { return id; }
