package com.thirdeye.backend.testgen;

import com.thirdeye.backend.entity.Finding;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Generates meaningful, deterministic test code for findings produced by the
 * static-analysis engine.
 *
 * <h3>Design principles</h3>
 * <ul>
 *   <li>Each test is derived from the finding's rule ID, file, line number,
 *       and the evidence snippet embedded in the finding description.</li>
 *   <li>No AI model, no external API, no randomness — output is 100%
 *       deterministic for a given finding.</li>
 *   <li>Tests are honest: they are marked {@code NOT_RUN} and include a
 *       clear comment stating they have not been executed.</li>
 *   <li>When the evidence is available, it is embedded verbatim as a comment
 *       so the developer knows exactly which line triggered the finding.</li>
 *   <li>When context is insufficient for a real assertion, a scaffold is
 *       generated with an explicit {@code // SCAFFOLD} comment explaining
 *       what must be implemented before the test has value.</li>
 * </ul>
 *
 * <h3>Supported rule IDs</h3>
 * <ul>
 *   <li>{@code SQLI-001} — SQL injection via string concatenation</li>
 *   <li>{@code CRED-001} — Hardcoded credential literal</li>
 *   <li>{@code EXEC-001} — Dangerous command execution</li>
 *   <li>{@code DESER-001} — Unsafe deserialization</li>
 *   <li>Any other rule → generic scaffold</li>
 * </ul>
 */
public final class TestCodeGenerator {

    /** Pattern to extract the Evidence: `...` snippet from finding descriptions. */
    private static final Pattern EVIDENCE_PATTERN =
            Pattern.compile("Evidence:\\s*`([^`]{1,300})`");

    // private constructor — utility class
    private TestCodeGenerator() {}

    // ── public API ─────────────────────────────────────────────────────────────

    /**
     * Generate test code for a finding.
     *
     * @param f the finding to generate a test for
     * @return a non-null, non-empty string of test source code
     */
    public static String generate(Finding f) {
        String ruleId = extractRuleId(f.getDescription());
        return switch (ruleId) {
            case "SQLI-001"  -> sqlInjectionTest(f);
            case "CRED-001"  -> hardcodedCredentialTest(f);
            case "EXEC-001"  -> dangerousExecutionTest(f);
            case "DESER-001" -> unsafeDeserializationTest(f);
            default          -> genericScaffold(f, ruleId);
        };
    }

    /**
     * Determine the test type label for a finding (used to tag the
     * {@code GeneratedTest.testType} field).
     */
    public static String testType(Finding f) {
        return extractRuleId(f.getDescription());
    }

    /**
     * Generate the suggested test file path for a finding.
     * Path mirrors the source file with a {@code Test} suffix inserted.
     */
    public static String testFilePath(Finding f) {
        String srcFile = f.getFile() == null ? "unknown" : f.getFile();
        String rule    = testType(f).replace("-", "_").toLowerCase();
        // strip leading src/main/java/ if present
        String normalized = srcFile.replaceFirst("^src/main/java/", "");
        String base = normalized.replaceFirst("\\.[^.]+$", ""); // drop extension
        base = base.replaceAll("[^a-zA-Z0-9/_-]", "_");
        return "src/test/java/" + base + "_" + rule + "_finding" + f.getId() + "_Test.java";
    }

    // ── rule-specific generators ───────────────────────────────────────────────

    private static String sqlInjectionTest(Finding f) {
        String evidence = extractEvidence(f.getDescription());
        String className = safeClassName(f.getFile()) + "SqlInjectionTest";
        String file = f.getFile() == null ? "unknown" : f.getFile();

        return header(f, "SQLI-001") +
               "/**\n" +
               " * Verifies that the SQL query in " + file + " (line " + f.getLine() + ")\n" +
               " * is NOT built by string concatenation of untrusted input.\n" +
               " *\n" +
               " * Finding: " + f.getTitle() + "\n" +
               " * Severity: " + f.getSeverity() + "\n" +
               " *\n" +
               " * Offending code detected at line " + f.getLine() + ":\n" +
               " *   " + evidence + "\n" +
               " *\n" +
               " * HOW TO COMPLETE THIS TEST:\n" +
               " * 1. Inject SQL metacharacters (e.g. ' OR '1'='1) as a method argument.\n" +
               " * 2. Assert the query uses PreparedStatement with '?' placeholders, OR\n" +
               " *    assert that a SecurityException / validation error is thrown.\n" +
               " * 3. Assert the raw metacharacter is NOT present in the final SQL string.\n" +
               " */\n" +
               "// SCAFFOLD — complete the assertions below before relying on this test\n" +
               "class " + className + " {\n\n" +
               "    @Test\n" +
               "    @DisplayName(\"SQL query at " + file + ":" + f.getLine() +
                              " must not concatenate user input\")\n" +
               "    void sqlQuery_mustNotConcatenateUserInput() {\n" +
               "        // ── Arrange ─────────────────────────────────────────────────────\n" +
               "        // Provide a value containing SQL metacharacters.\n" +
               "        // If the method under test does not sanitise this, the query is\n" +
               "        // injectable.\n" +
               "        String maliciousInput = \"' OR '1'='1\";\n\n" +
               "        // ── Act ──────────────────────────────────────────────────────────\n" +
               "        // TODO: call the method that builds the query, passing maliciousInput.\n" +
               "        // Example: String actualQuery = subjectUnderTest.buildQuery(maliciousInput);\n\n" +
               "        // ── Assert ───────────────────────────────────────────────────────\n" +
               "        // Option A — assert the metacharacter was NOT embedded verbatim:\n" +
               "        // assertThat(actualQuery).doesNotContain(maliciousInput);\n\n" +
               "        // Option B — assert a PreparedStatement was used (mock verification):\n" +
               "        // verify(mockConnection).prepareStatement(anyString());\n\n" +
               "        // SCAFFOLD: replace the line below with the real assertion above.\n" +
               "        fail(\"Test not yet implemented — see scaffold instructions above.\");\n" +
               "    }\n" +
               "}\n";
    }

    private static String hardcodedCredentialTest(Finding f) {
        String evidence = extractEvidence(f.getDescription());
        String className = safeClassName(f.getFile()) + "HardcodedCredentialTest";
        String file = f.getFile() == null ? "unknown" : f.getFile();

        return header(f, "CRED-001") +
               "/**\n" +
               " * Verifies that the credential in " + file + " (line " + f.getLine() + ")\n" +
               " * is NOT a hardcoded string literal — it must be loaded from an\n" +
               " * environment variable, a secrets manager, or a @Value property.\n" +
               " *\n" +
               " * Finding: " + f.getTitle() + "\n" +
               " * Severity: " + f.getSeverity() + "\n" +
               " *\n" +
               " * Offending code detected at line " + f.getLine() + ":\n" +
               " *   " + evidence + "\n" +
               " *\n" +
               " * HOW TO COMPLETE THIS TEST:\n" +
               " * 1. Ensure the class under test receives its credential via constructor\n" +
               " *    injection or @Value, NOT as a string literal.\n" +
               " * 2. Assert that getenv(\"SECRET_KEY\") (or equivalent) is called, OR\n" +
               " *    that the field value is not equal to the hardcoded literal.\n" +
               " */\n" +
               "// SCAFFOLD — complete the assertions below before relying on this test\n" +
               "class " + className + " {\n\n" +
               "    @Test\n" +
               "    @DisplayName(\"Credential at " + file + ":" + f.getLine() +
                              " must not be a hardcoded literal\")\n" +
               "    void credential_mustNotBeHardcoded() {\n" +
               "        // ── Assert ───────────────────────────────────────────────────────\n" +
               "        // Verify that no hardcoded secret literal is used.\n\n" +
               "        // Option A — reflection check that the field is null or blank when\n" +
               "        //            no environment variable is set:\n" +
               "        // String secret = System.getenv(\"MY_SECRET\");\n" +
               "        // assertThat(secret).isNotBlank();\n\n" +
               "        // Option B — instantiate the class with a test @Value and assert\n" +
               "        //            the injected value equals the env var, not a literal:\n" +
               "        // SubjectUnderTest sut = new SubjectUnderTest(System.getenv(\"MY_SECRET\"));\n" +
               "        // assertThat(sut.getCredential()).isEqualTo(System.getenv(\"MY_SECRET\"));\n\n" +
               "        // SCAFFOLD: replace the line below with the real assertion above.\n" +
               "        fail(\"Test not yet implemented — see scaffold instructions above.\");\n" +
               "    }\n" +
               "}\n";
    }

    private static String dangerousExecutionTest(Finding f) {
        String evidence = extractEvidence(f.getDescription());
        String className = safeClassName(f.getFile()) + "DangerousExecutionTest";
        String file = f.getFile() == null ? "unknown" : f.getFile();

        return header(f, "EXEC-001") +
               "/**\n" +
               " * Verifies that the command execution in " + file + " (line " + f.getLine() + ")\n" +
               " * is safe: either it does not accept user-supplied arguments, or\n" +
               " * it validates/allowlists them before constructing the command.\n" +
               " *\n" +
               " * Finding: " + f.getTitle() + "\n" +
               " * Severity: " + f.getSeverity() + "\n" +
               " *\n" +
               " * Offending code detected at line " + f.getLine() + ":\n" +
               " *   " + evidence + "\n" +
               " *\n" +
               " * HOW TO COMPLETE THIS TEST:\n" +
               " * 1. Call the method with shell-injection payloads (e.g. \"; rm -rf /\").\n" +
               " * 2. Assert that an IllegalArgumentException (or similar) is thrown, OR\n" +
               " *    that the injected payload is not present in the executed command.\n" +
               " * 3. If using ProcessBuilder, verify the command list is constructed from\n" +
               " *    a fixed allowlist rather than string concatenation.\n" +
               " */\n" +
               "// SCAFFOLD — complete the assertions below before relying on this test\n" +
               "class " + className + " {\n\n" +
               "    @Test\n" +
               "    @DisplayName(\"Command at " + file + ":" + f.getLine() +
                              " must not accept shell-injection payloads\")\n" +
               "    void commandExecution_mustRejectShellInjection() {\n" +
               "        // ── Arrange ─────────────────────────────────────────────────────\n" +
               "        String shellInjectionPayload = \"; rm -rf /\";\n\n" +
               "        // ── Act + Assert ─────────────────────────────────────────────────\n" +
               "        // TODO: call the method that builds the OS command.\n" +
               "        // Example:\n" +
               "        // assertThatThrownBy(() -> subjectUnderTest.execute(shellInjectionPayload))\n" +
               "        //     .isInstanceOf(IllegalArgumentException.class);\n\n" +
               "        // SCAFFOLD: replace the line below with the real assertion above.\n" +
               "        fail(\"Test not yet implemented — see scaffold instructions above.\");\n" +
               "    }\n" +
               "}\n";
    }

    private static String unsafeDeserializationTest(Finding f) {
        String evidence = extractEvidence(f.getDescription());
        String className = safeClassName(f.getFile()) + "UnsafeDeserializationTest";
        String file = f.getFile() == null ? "unknown" : f.getFile();

        return header(f, "DESER-001") +
               "/**\n" +
               " * Verifies that the deserialization at " + file + " (line " + f.getLine() + ")\n" +
               " * is protected against gadget-chain attacks: either the ObjectInputStream\n" +
               " * validates the incoming class against an allowlist, or a safer\n" +
               " * deserialization library is used.\n" +
               " *\n" +
               " * Finding: " + f.getTitle() + "\n" +
               " * Severity: " + f.getSeverity() + "\n" +
               " *\n" +
               " * Offending code detected at line " + f.getLine() + ":\n" +
               " *   " + evidence + "\n" +
               " *\n" +
               " * HOW TO COMPLETE THIS TEST:\n" +
               " * 1. Serialize a crafted object whose class is NOT on any expected allowlist.\n" +
               " * 2. Feed the byte stream to the method under test.\n" +
               " * 3. Assert that an InvalidClassException or custom rejection is thrown.\n" +
               " * 4. Alternatively, assert that a safe library (e.g. Jackson with type\n" +
               " *    restrictions) is used instead of raw ObjectInputStream.\n" +
               " */\n" +
               "// SCAFFOLD — complete the assertions below before relying on this test\n" +
               "class " + className + " {\n\n" +
               "    @Test\n" +
               "    @DisplayName(\"Deserialization at " + file + ":" + f.getLine() +
                              " must reject untrusted class types\")\n" +
               "    void deserialization_mustRejectUntrustedTypes() {\n" +
               "        // ── Arrange ─────────────────────────────────────────────────────\n" +
               "        // Serialize a known-unsafe gadget type to a byte array.\n" +
               "        // byte[] payload = serializeObject(new SomeGadgetClass());\n\n" +
               "        // ── Act + Assert ─────────────────────────────────────────────────\n" +
               "        // TODO: feed the payload to the method under test.\n" +
               "        // Example:\n" +
               "        // assertThatThrownBy(() -> subjectUnderTest.deserialize(payload))\n" +
               "        //     .isInstanceOf(InvalidClassException.class);\n\n" +
               "        // SCAFFOLD: replace the line below with the real assertion above.\n" +
               "        fail(\"Test not yet implemented — see scaffold instructions above.\");\n" +
               "    }\n" +
               "}\n";
    }

    private static String genericScaffold(Finding f, String ruleId) {
        String file = f.getFile() == null ? "unknown" : f.getFile();
        String evidence = extractEvidence(f.getDescription());
        String className = safeClassName(f.getFile()) + "FindingTest";

        return header(f, ruleId) +
               "/**\n" +
               " * Scaffold for finding: " + f.getTitle() + "\n" +
               " * Rule: " + ruleId + "  |  Severity: " + f.getSeverity() +
                              "  |  File: " + file + ":" + f.getLine() + "\n" +
               " *\n" +
               " * Detected code:\n" +
               " *   " + evidence + "\n" +
               " *\n" +
               " * Suggestion: " + (f.getSuggestion() == null ? "see finding description" : f.getSuggestion()) + "\n" +
               " */\n" +
               "// SCAFFOLD — implement the body before using this test\n" +
               "class " + className + " {\n\n" +
               "    @Test\n" +
               "    @DisplayName(\"" + escapeJava(f.getTitle()) + " — " + file + ":" + f.getLine() + "\")\n" +
               "    void finding_mustBeRemediated() {\n" +
               "        // TODO: write a test that verifies the issue has been addressed.\n" +
               "        // Refer to the suggestion in the finding description.\n" +
               "        fail(\"Test not yet implemented.\");\n" +
               "    }\n" +
               "}\n";
    }

    // ── shared header ─────────────────────────────────────────────────────────

    /**
     * Common import/annotation block shared by all generated tests.
     * Output is a valid Java compilation unit when combined with a class body.
     */
    private static String header(Finding f, String ruleId) {
        return "// ─────────────────────────────────────────────────────────────────────────\n" +
               "// GENERATED BY ThirdEye static-analysis test generator\n" +
               "// Rule: " + ruleId + "  |  Finding #" + f.getId() +
                              "  |  Status: NOT_RUN  (never executed)\n" +
               "// This test was produced deterministically from finding metadata.\n" +
               "// Complete the SCAFFOLD sections before treating this as a real test.\n" +
               "// ─────────────────────────────────────────────────────────────────────────\n\n" +
               "import org.junit.jupiter.api.DisplayName;\n" +
               "import org.junit.jupiter.api.Test;\n" +
               "import static org.assertj.core.api.Assertions.assertThat;\n" +
               "import static org.assertj.core.api.Assertions.assertThatThrownBy;\n" +
               "import static org.junit.jupiter.api.Assertions.fail;\n\n";
    }

    // ── helpers ───────────────────────────────────────────────────────────────

    /** Extract the rule ID from the leading "[RULE-ID]" tag in a finding description. */
    static String extractRuleId(String description) {
        if (description == null) return "UNKNOWN";
        // Descriptions start with "[SQLI-001] ..." or "[CRED-001] ..." etc.
        int start = description.indexOf('[');
        int end   = description.indexOf(']');
        if (start >= 0 && end > start) {
            String candidate = description.substring(start + 1, end).trim();
            // Accept rule IDs matching pattern WORD-NNN
            if (candidate.matches("[A-Z]+-\\d{3}")) return candidate;
        }
        return "UNKNOWN";
    }

    /** Extract the evidence snippet from "Evidence: `...`" in the description. */
    static String extractEvidence(String description) {
        if (description == null) return "(no evidence available)";
        Matcher m = EVIDENCE_PATTERN.matcher(description);
        return m.find() ? m.group(1) : "(no evidence available)";
    }

    /** Derive a safe Java class-name prefix from a file path. */
    private static String safeClassName(String file) {
        if (file == null || file.isBlank() || "unknown".equals(file)) return "Unknown";
        // Take last path segment, strip extension, capitalize first letter
        String base = file.contains("/") ? file.substring(file.lastIndexOf('/') + 1) : file;
        base = base.replaceFirst("\\.[^.]+$", ""); // drop extension
        base = base.replaceAll("[^a-zA-Z0-9]", "_");
        if (base.isEmpty()) return "Unknown";
        return Character.toUpperCase(base.charAt(0)) + base.substring(1);
    }

    private static String escapeJava(String s) {
        return s == null ? "" : s.replace("\"", "\\\"");
    }
}

