        // Descriptions start with "[SQLI-001] ..." or "[CRED-001] ..." etc.
        int start = description.indexOf('[');
        int end   = description.indexOf(']');
        if (start >= 0 && end > start) {
            String candidate = description.substring(start + 1, end).trim();
