        base = base.replaceAll("[^a-zA-Z0-9]", "_");
        if (base.isEmpty()) return "Unknown";
        return Character.toUpperCase(base.charAt(0)) + base.substring(1);
    }

    private static String escapeJava(String s) {
        return s == null ? "" : s.replace("\"", "\\\"");
    }
