    }

    /**
     * Generates mock test stubs for each finding in the review.
     * Idempotent — clears existing tests before regenerating.
     *
     * @param reviewId review to generate tests for
     * @return list of generated tests
     * @throws ResourceNotFoundException if review not found
     * @throws IllegalStateException if review is not yet COMPLETED
     */
    @Transactional
    public List<GeneratedTest> generateTests(Long reviewId) {
        Review review = getReviewOrThrow(reviewId);

        if (!"COMPLETED".equals(review.getStatus())) {
            throw new IllegalArgumentException(
                "Tests can only be generated for COMPLETED reviews. Current status: " + review.getStatus());
        }

        // Clear previous generated tests (idempotent)
        testRepository.deleteByReview_Id(reviewId);

        List<Finding> findings = findingRepository.findByReview_Id(reviewId);
        List<GeneratedTest> tests = new ArrayList<>();

        for (Finding f : findings) {
            String testName = buildTestName(f);
            String testCode = buildTestCode(f);
            String filename = buildFilename(f);

            tests.add(new GeneratedTest(
                review,
                testName,
                filename,
                "PENDING",   // [MOCK] Tests are never actually executed
                null,
                String.valueOf(f.getId()),
                testCode
            ));
        }

        // Add one general review-level test
        tests.add(new GeneratedTest(
            review,
            "diff does not introduce new critical security findings",
            "tests/security/review_" + reviewId + "_security.test.js",
            "PENDING",
            null,
            null,
            buildSecuritySmokeTest(review)
        ));

        List<GeneratedTest> saved = testRepository.saveAll(tests);
        log.info("[MOCK] Generated {} test stubs for review {}", saved.size(), reviewId);
        return saved;
