            case "high":     return "should reject unsafe input: " + lowerFirst(f.getTitle());
            case "medium":   return "should handle edge case: " + lowerFirst(f.getTitle());
            default:         return "should satisfy: " + lowerFirst(f.getTitle());
        }
    }

    private String buildFilename(Finding f) {
        String base = f.getFile() == null ? "unknown" : f.getFile()
