                .replaceFirst("\\.[^.]+$", "");
        return "tests/" + base + "_finding_" + f.getId() + ".test.js";
    }

    private String buildTestCode(Finding f) {
        return "// [MOCK GENERATED TEST] — not executed\n" +
               "// Finding: " + f.getTitle() + "\n" +
               "// Severity: " + f.getSeverity() + " | Category: " + f.getCategory() + "\n" +
               "// File: " + f.getFile() + ":" + f.getLine() + "\n\n" +
               "describe('" + escapeJs(f.getTitle()) + "', () => {\n" +
               "  it('" + escapeJs(buildTestName(f)) + "', () => {\n" +
               "    // TODO: implement test for finding #" + f.getId() + "\n" +
               "    // Suggestion: " + (f.getSuggestion() == null ? "see finding description" : f.getSuggestion()) + "\n" +
               "    expect(true).toBe(true); // placeholder\n" +
               "  });\n" +
               "});\n";
    }

    private String buildSecuritySmokeTest(Review review) {
        return "// [MOCK GENERATED TEST] — not executed\n" +
               "// Review #" + review.getId() + ": " + review.getTitle() + "\n\n" +
               "describe('Review #" + review.getId() + " security smoke test', () => {\n" +
               "  it('diff does not introduce new critical security findings', () => {\n" +
               "    // This test would assert that the code changes do not\n" +
               "    // introduce hardcoded credentials, injection vectors, etc.\n" +
               "    expect(true).toBe(true); // placeholder — replace with real assertions\n" +
               "  });\n" +
               "});\n";
    }

    private String lowerFirst(String s) {
        if (s == null || s.isEmpty()) return s;
        return Character.toLowerCase(s.charAt(0)) + s.substring(1);
    }

    private String escapeJs(String s) {
        return s == null ? "" : s.replace("'", "\\'");
    }

    private Review getReviewOrThrow(Long reviewId) {
        return reviewRepository.findById(reviewId)
                .orElseThrow(() -> new ResourceNotFoundException(
                        "Review not found with id: " + reviewId));
    }
